import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import toast from 'react-hot-toast';
import './UserDashboard.css';

const UserDashboard = () => {
  const [leads, setLeads] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    fetchLeads();
  }, []);

  const fetchLeads = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/leads', {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      setLeads(response.data.data);
    } catch (error) {
      toast.error('Failed to load leads');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
    toast.success('Logged out');
  };

  const handleSaveLead = async (leadId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.put(
        `http://localhost:5000/api/leads/${leadId}/save`,
        {},
        {
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      );
      toast.success('Lead saved successfully');
      fetchLeads();
    } catch (error) {
      toast.error('Failed to save lead');
    }
  };

  if (loading) {
    return <div className="loading">Loading...</div>;
  }

  return (
    <div className="user-dashboard">
      <header className="dashboard-header">
        <h1>User Dashboard</h1>
        <button onClick={handleLogout} className="logout-btn">
          Logout
        </button>
      </header>

      <div className="leads-section">
        <h2>Your Leads</h2>
        <div className="leads-grid">
          {leads.length === 0 ? (
            <p>No leads found</p>
          ) : (
            leads.map((lead) => (
              <div key={lead._id} className="lead-card">
                <h3>{lead.companyName}</h3>
                <p>
                  <strong>Email:</strong> {lead.email || 'N/A'}
                </p>
                <p>
                  <strong>Industry:</strong> {lead.industry || 'N/A'}
                </p>
                <p>
                  <strong>Status:</strong>{' '}
                  <span className={`status-${lead.status}`}>{lead.status}</span>
                </p>
                {!lead.isSaved ? (
                  <button onClick={() => handleSaveLead(lead._id)}>
                    Save Lead
                  </button>
                ) : (
                  <span className="saved-badge">⭐ Saved</span>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default UserDashboard;
